#[allow(unused_imports)]
pub(crate) use stage3;

#[cfg(test)]
mod tests {
    use super::*;

    // TODO(port-dedupe): replace with crate::font::glyph::Constraint
    // (and its Size/Align/Height enums) once Glyph.zig is ported.
    #[derive(Debug, Clone, Copy, PartialEq)]
    enum Size {
        None,
        Fit,
        Cover,
        FitCover1,
        Stretch,
    }

    #[derive(Debug, Clone, Copy, PartialEq)]
    enum Align {
        None,
        Start,
        End,
        Center,
        Center1,
    }

    #[derive(Debug, Clone, Copy, PartialEq)]
    enum Height {
        Cell,
        Icon,
    }

    #[derive(Debug, Clone, Copy, PartialEq)]
    struct Constraint {
        size: Size,
        align_vertical: Align,
        align_horizontal: Align,
        pad_top: f64,
        pad_left: f64,
        pad_right: f64,
        pad_bottom: f64,
        relative_width: f64,
        relative_height: f64,
        relative_x: f64,
        relative_y: f64,
        max_xy_ratio: Option<f64>,
        max_constraint_width: u8,
        height: Height,
    }

    impl Constraint {
        const NONE: Constraint = Constraint {
            size: Size::None,
            align_vertical: Align::None,
            align_horizontal: Align::None,
            pad_top: 0.0,
            pad_left: 0.0,
            pad_right: 0.0,
            pad_bottom: 0.0,
            relative_width: 1.0,
            relative_height: 1.0,
            relative_x: 0.0,
            relative_y: 0.0,
            max_xy_ratio: None,
            max_constraint_width: 2,
            height: Height::Cell,
        };
    }

    static STAGE3: [Option<Constraint>; STAGE3_LEN] = stage3!(Constraint, Size, Align, Height);

    #[test]
    fn layout_invariants() {
        // One stage1 entry for every high byte of a u21.
        assert_eq!(0x2000, STAGE1.len());
        // stage3[0] must be null.
        assert!(!STAGE3.is_empty());
        assert_eq!(None, STAGE3[0]);
        // The empty nerd-font page must be stage2 offset 0.
        assert!(STAGE2[0..256].iter().all(|&e| e == 0));
        // Every stage1 entry is a page offset, every stage2 entry a stage3 index.
        assert!(STAGE1.iter().all(|&o| o as usize % 256 == 0 && (o as usize) < STAGE2.len()));
        assert!(STAGE2.iter().all(|&i| (i as usize) < STAGE3.len()));
        assert_eq!(277, STAGE3_LEN);
    }

    #[test]
    fn stage3_entries() {
        assert_eq!(
            Some(Constraint {
                size: Size::FitCover1,
                height: Height::Icon,
                align_horizontal: Align::Center1,
                align_vertical: Align::Center1,
                ..Constraint::NONE
            }),
            STAGE3[1],
        );
        assert_eq!(
            Some(Constraint {
                size: Size::Cover,
                height: Height::Icon,
                max_constraint_width: 1,
                align_horizontal: Align::Center1,
                align_vertical: Align::Center1,
                pad_left: 0.05,
                pad_right: 0.05,
                pad_top: 0.05,
                pad_bottom: 0.05,
                ..Constraint::NONE
            }),
            STAGE3[2],
        );
        // All entries but the first are constraints.
        assert!(STAGE3[1..].iter().all(|c| c.is_some()));
        // Every enum variant used by the generator is reachable.
        let _ = (Size::Fit, Align::Start, Align::End, Align::Center, Size::Stretch);
    }
}
